#define DMX_GRAPH_NO_MAIN
#include "dmx_graph.cpp"
#include "disk_model_metadata_cache.h"
#include "model_flex_lookup.h"
#include <iostream>
int main(int argc,char**argv){try{static_assert(sizeof(void*)==8,"x64 required");if(argc!=3)throw std::runtime_error("session and explicit content root required");auto g=loadGraph(argv[1]);auto root=std::filesystem::weakly_canonical(argv[2]);DiskModelMetadataCacheCandidate cache;RecoveredGlobalFlexRegistryCandidate registry;unsigned linked=0,matched=0,missingAsset=0,missingName=0;auto attr=[&](const Element&e,const std::string&name)->const Attribute*{for(auto&a:e.attributes)if(g.strings.at(a.name)==name)return &a;return nullptr;};for(uint32_t modelId=0;modelId<g.elements.size();++modelId){auto&model=g.elements[modelId];if(g.strings.at(model.type)!="DmeGameModel")continue;auto name=attr(model,"modelName");if(!name||name->type!=5||name->values.size()!=1)continue;std::filesystem::path relative=name->values[0].text;if(relative.is_absolute())throw std::runtime_error("absolute model asset");for(auto&part:relative)if(part=="..")throw std::runtime_error("model traversal");auto file=std::filesystem::weakly_canonical(root/relative);auto inside=file.lexically_relative(root);if(inside.empty()||*inside.begin()=="..")throw std::runtime_error("model outside content root");uint16_t handle=cache.acquire(file);auto records=cache.controllers(handle);std::vector<uint32_t>weights;auto saved=attr(model,"flexWeights");if(saved&&saved->type==17)for(auto&v:saved->values)weights.push_back(wireU32(v));unsigned localLinked=0,localMatched=0;for(uint32_t id=0;id<g.elements.size();++id){auto&op=g.elements[id];if(g.strings.at(op.type)!="DmeGlobalFlexControllerOperator")continue;auto target=attr(op,"gameModel");if(!target||target->type!=1||target->values.size()!=1||target->values[0].reference!=modelId)continue;++linked;++localLinked;if(!records){++missingAsset;continue;}auto index=recoveredModelFlexLookupCandidate(records,g.strings.at(op.name),weights,&registry);if(index!=0xffffffffu){++matched;++localMatched;}else{++missingName;std::cout<<"missing_controller model="<<modelId<<" op="<<id<<" name="<<g.strings.at(op.name)<<'\n';}}std::cout<<"model="<<modelId<<" asset="<<relative.generic_string()<<" available="<<(records!=nullptr)<<" linked="<<localLinked<<" matched="<<localMatched<<" candidate_weight_count="<<weights.size()<<'\n';if(handle!=0xffff)cache.release(handle);}std::cout<<"linked="<<linked<<" matched="<<matched<<" missing_asset="<<missingAsset<<" missing_name="<<missingName<<" fresh_registry_size="<<registry.names().size()<<" historic_mapping=unverified graph_modified=no\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
